// Generated by AI (UnitTest MCP)
use crate::{now_unix, telemetry, MindLeak, Result};

/// Whether a recorded tool call succeeded, was refused as invalid or
/// unconfirmed input, or genuinely failed.
///
/// A refusal is the tool working correctly -- `reset_database` rejecting a
/// missing confirmation token is the guard doing its job, not a defect -- so
/// it is a distinct outcome from `Error`, never folded into it. Conflating
/// the two made a hard-guarded tool's lifetime failure rate read as 100% even
/// though nothing was ever broken (ADR-0010;
/// gaps.d/a-refused-call-is-counted-as-a-failed-call.md).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ToolOutcome {
    Ok,
    Refused,
    Error,
}

impl ToolOutcome {
    fn as_str(self) -> &'static str {
        match self {
            ToolOutcome::Ok => "ok",
            ToolOutcome::Refused => "refused",
            ToolOutcome::Error => "error",
        }
    }
}

impl MindLeak {
    /// Record one observability event about a tool invocation (ADR-0010).
    /// Best-effort: a telemetry write failure is logged and swallowed so it can
    /// never change the result of the operation being observed.
    pub fn record_tool_call(
        &self,
        tool: &str,
        outcome: ToolOutcome,
        duration_ms: i64,
        mut detail: Option<serde_json::Value>,
        agent_id: Option<&str>,
    ) {
        if let Some(agent_id) = agent_id {
            let value = detail.get_or_insert_with(|| serde_json::json!({}));
            if let Some(object) = value.as_object_mut() {
                object.insert("agent_id".to_string(), serde_json::json!(agent_id));
            }
        }
        if let Err(e) = telemetry::record(
            &self.store.conn,
            now_unix(),
            "tool_call",
            tool,
            outcome.as_str(),
            Some(duration_ms),
            detail.as_ref(),
        ) {
            tracing::warn!(target: "mindleak::telemetry", tool, error = %e, "failed to record telemetry");
        }
    }

    /// Record one autonomous maintenance pass without exposing it as a tool
    /// invocation. Best-effort for the same reason as tool telemetry.
    pub fn record_maintenance(
        &self,
        name: &str,
        outcome: &str,
        duration_ms: i64,
        detail: Option<serde_json::Value>,
    ) {
        if let Err(error) = telemetry::record(
            &self.store.conn,
            now_unix(),
            "maintenance",
            name,
            outcome,
            Some(duration_ms),
            detail.as_ref(),
        ) {
            tracing::warn!(target: "mindleak::telemetry", name, %error, "failed to record maintenance telemetry");
        }
    }

    /// A point-in-time observability snapshot: aggregate metrics per tool plus
    /// the most recent `recent_limit` events (ADR-0010).
    pub fn telemetry_snapshot(&self, recent_limit: usize) -> Result<telemetry::Snapshot> {
        telemetry::snapshot(&self.store.conn, recent_limit)
    }

    /// Optional work that has been failing long enough to be worth volunteering.
    ///
    /// A degraded pass is recorded once and then goes quiet on purpose, which is
    /// right for a blip and wrong for an outage: the autonomous index went 121
    /// consecutive passes unreachable and every report of it looked like the
    /// first. Cheap enough for `open_session` to ask on every call.
    pub fn sustained_degradation(&self) -> Result<Vec<telemetry::Sustained>> {
        telemetry::sustained_degradation(&self.store.conn, crate::now_unix())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn maintenance_telemetry_is_distinct_from_tool_calls() {
        let engine = MindLeak::open_in_memory().unwrap();

        engine.record_maintenance(
            "autonomous_consolidation",
            "skipped",
            3,
            Some(serde_json::json!({ "reason": "no_candidates" })),
        );

        let snapshot = engine.telemetry_snapshot(1).unwrap();
        assert_eq!(snapshot.recent[0].kind, "maintenance");
        assert_eq!(snapshot.recent[0].outcome, "skipped");
    }

    #[test]
    fn record_tool_call_reports_ok_error_and_refused_outcomes() {
        let engine = MindLeak::open_in_memory().unwrap();

        engine.record_tool_call("recall", ToolOutcome::Ok, 12, None, None);
        engine.record_tool_call("recall", ToolOutcome::Error, 7, None, None);
        engine.record_tool_call("reset_database", ToolOutcome::Refused, 1, None, None);

        let snapshot = engine.telemetry_snapshot(3).unwrap();
        assert_eq!(snapshot.recent[0].kind, "tool_call");
        assert_eq!(snapshot.recent[0].outcome, "refused");
        assert_eq!(snapshot.recent[1].outcome, "error");
        assert_eq!(snapshot.recent[2].outcome, "ok");
    }

    /// Regression: a refused call (a working guard, not a defect) must never
    /// inflate a tool's error count or make it read as currently failing --
    /// see gaps.d/a-refused-call-is-counted-as-a-failed-call.md. It still
    /// counts toward `calls` and its own `refused` tally, so the information
    /// is re-bucketed correctly, not silently dropped.
    #[test]
    fn a_refused_call_never_counts_as_an_error() {
        let engine = MindLeak::open_in_memory().unwrap();

        engine.record_tool_call("reset_database", ToolOutcome::Refused, 1, None, None);
        engine.record_tool_call("reset_database", ToolOutcome::Refused, 1, None, None);
        engine.record_tool_call("reset_database", ToolOutcome::Ok, 1, None, None);

        let snapshot = engine.telemetry_snapshot(1).unwrap();
        let metric = snapshot
            .by_name
            .iter()
            .find(|m| m.name == "reset_database")
            .unwrap();
        assert_eq!(metric.calls, 3);
        assert_eq!(metric.errors, 0);
        assert_eq!(metric.refused, 2);
        assert!(!metric.currently_failing);
    }

    #[test]
    fn record_tool_call_with_no_agent_id_leaves_detail_untouched() {
        let engine = MindLeak::open_in_memory().unwrap();

        engine.record_tool_call(
            "recall",
            ToolOutcome::Ok,
            5,
            Some(serde_json::json!({ "query": "resolve_database" })),
            None,
        );

        let snapshot = engine.telemetry_snapshot(1).unwrap();
        assert_eq!(
            snapshot.recent[0].detail,
            Some(serde_json::json!({ "query": "resolve_database" }))
        );
    }

    #[test]
    fn record_tool_call_injects_agent_id_into_a_fresh_detail_object_when_none_was_given() {
        let engine = MindLeak::open_in_memory().unwrap();

        engine.record_tool_call("recall", ToolOutcome::Ok, 5, None, Some("agent:v1:abc"));

        let snapshot = engine.telemetry_snapshot(1).unwrap();
        assert_eq!(
            snapshot.recent[0].detail,
            Some(serde_json::json!({ "agent_id": "agent:v1:abc" }))
        );
    }

    #[test]
    fn record_tool_call_merges_agent_id_into_an_existing_detail_object() {
        let engine = MindLeak::open_in_memory().unwrap();

        engine.record_tool_call(
            "recall",
            ToolOutcome::Ok,
            5,
            Some(serde_json::json!({ "query": "resolve_database" })),
            Some("agent:v1:abc"),
        );

        let snapshot = engine.telemetry_snapshot(1).unwrap();
        assert_eq!(
            snapshot.recent[0].detail,
            Some(serde_json::json!({
                "query": "resolve_database",
                "agent_id": "agent:v1:abc"
            }))
        );
    }

    /// `record_tool_call`/`record_maintenance` are best-effort: a telemetry
    /// write failure must be swallowed, never surfaced to the caller.
    /// Pre-creating an incompatible `telemetry_events` table makes
    /// `ensure_table`'s `CREATE TABLE IF NOT EXISTS` a no-op and the real
    /// insert fail for real -- confirmed directly below, so the sabotage
    /// itself is proven rather than assumed.
    #[test]
    fn a_telemetry_write_failure_is_swallowed_rather_than_propagated() {
        let engine = MindLeak::open_in_memory().unwrap();
        engine
            .store
            .conn
            .execute_batch("CREATE TABLE telemetry_events (only_column TEXT NOT NULL);")
            .unwrap();

        let raw_insert = engine.store.conn.execute(
            "INSERT INTO telemetry_events (ts, kind, name, outcome, duration_ms, detail) \
             VALUES (1, 'x', 'y', 'z', NULL, NULL)",
            [],
        );
        assert!(
            raw_insert.is_err(),
            "the sabotaged schema must make the real insert shape fail"
        );

        // Both return () and must not panic despite that same failure.
        engine.record_tool_call("recall", ToolOutcome::Ok, 5, None, None);
        engine.record_maintenance("autonomous_prune", "ok", 1, None);
    }
}
